"""Check that .codacy.yml excludes every generated file and keeps TSQLLint off the migrations.

A tracked file is generated when one of its first five lines carries a generator header
(Go "Code generated ... DO NOT EDIT." or "auto-generated by"). Each such file must match a
top-level exclude_paths entry: an exact path, or a "dir/**" prefix. --self-test runs the
planted cases.
"""

from __future__ import annotations

import argparse
import re
import subprocess  # nosec B404 -- runs only git with a fixed argument list, never a shell
import sys
from pathlib import Path

import yaml

CONFIG = ".codacy.yml"
MIGRATIONS = "api/internal/store/migrations/postgres/**"
HEADER = re.compile(r"Code generated .*DO NOT EDIT\.|auto-generated by")
HEAD_LINES = 5
GIT_TIMEOUT_SECONDS = 30
ROOT = Path(__file__).resolve().parents[2]


class UniqueKeyLoader(yaml.SafeLoader):
    """SafeLoader that refuses a duplicate mapping key instead of keeping the last one."""

    def construct_mapping(self, node: yaml.MappingNode, deep: bool = False) -> dict:
        """Build the mapping, raising on a key that appears twice."""
        seen: set = set()
        for key_node, _ in node.value:
            key = self.construct_object(key_node, deep=deep)
            if key in seen:
                raise yaml.constructor.ConstructorError(
                    None, None, f"duplicate key {key!r}", key_node.start_mark
                )
            seen.add(key)
        return super().construct_mapping(node, deep=deep)


def load_unique(text: str) -> object:
    """Parse one YAML document with UniqueKeyLoader (what yaml.load does, without naming a loader there)."""
    loader = UniqueKeyLoader(text)
    try:
        return loader.get_single_data()
    finally:
        loader.dispose()


def is_generated(text: str) -> bool:
    """Report whether one of the first HEAD_LINES lines carries a generator header."""
    return any(HEADER.search(line) for line in text.splitlines()[:HEAD_LINES])


def covered(path: str, patterns: list[str]) -> bool:
    """Report whether an exact entry or a "dir/**" entry matches path."""
    for pattern in patterns:
        if pattern.endswith("/**") and path.startswith(pattern[:-2]):
            return True
        if pattern == path:
            return True
    return False


def problems(config_text: str, files: dict[str, str]) -> list[str]:
    """Return one message per uncovered generated file or missing TSQLLint exclusion."""
    if not config_text.startswith("---"):
        return [f"{CONFIG} must start with ---"]
    try:
        config = load_unique(config_text) or {}
    except yaml.YAMLError as err:
        return [f"{CONFIG}: {err}"]
    patterns = [str(p) for p in config.get("exclude_paths") or []]
    out = [
        f"{path}: generated file outside {CONFIG} exclude_paths"
        for path, text in sorted(files.items())
        if is_generated(text) and not covered(path, patterns)
    ]
    engines = config.get("engines") or {}
    tsql = (engines.get("tsqllint") or {}).get("exclude_paths") or []
    if MIGRATIONS not in tsql:
        out.append(f"{CONFIG}: engines.tsqllint.exclude_paths lacks {MIGRATIONS}")
    return out


def tracked_files() -> dict[str, str]:
    """Read the head of every tracked text file, from the repository root whatever the caller's directory."""
    names = subprocess.run(  # nosec B603 -- fixed git argv list, no shell, no caller input
        ["git", "ls-files", "-z"], check=True, capture_output=True, timeout=GIT_TIMEOUT_SECONDS, cwd=ROOT
    ).stdout.decode().split("\0")
    out: dict[str, str] = {}
    for name in filter(None, names):
        path = ROOT / name
        if not path.is_file():
            continue
        try:
            with path.open(encoding="utf-8") as handle:
                out[name] = "".join(handle.readline() for _ in range(HEAD_LINES))
        except UnicodeDecodeError:
            continue
    return out


def self_test() -> int:
    """Run planted cases; each must give the expected verdict."""
    good = '---\nexclude_paths:\n  - "gen/**"\n  - "a.ts"\nengines:\n  tsqllint:\n    exclude_paths:\n      - "' + MIGRATIONS + '"\n'
    gen = "// Code generated by ogen, DO NOT EDIT.\npackage x\n"
    cases = [
        ("covered by prefix and exact path", good, {"gen/x.go": gen, "a.ts": " * auto-generated by openapi-typescript\n"}, 0),
        ("hand-written file needs no entry", good, {"src/x.go": "package x\n"}, 0),
        ("generator source with header text late", good, {"tool.go": "package x\n\n\n\n\n// Code generated by t. DO NOT EDIT.\n"}, 0),
        ("generated file outside exclude_paths", good, {"other/x.go": gen}, 1),
        ("prefix is not a sibling match", good, {"genx/y.go": gen}, 1),
        ("tsqllint exclusion missing", good.split("engines:")[0], {}, 1),
        ("missing document start", good[4:], {}, 1),
        # The valid copy comes last, so only the duplicate-key refusal can fail these.
        ("duplicate engines key refused", "---\nengines:\n  other: {}\n" + good[4:], {}, 1),
        ("duplicate exclude_paths key refused", "---\nexclude_paths: []\n" + good[4:], {"gen/x.go": gen}, 1),
    ]
    failed = 0
    for name, text, files, want in cases:
        got = len(problems(text, files))
        if (got > 0) != (want > 0):
            print(f"FAIL {name}: {got} problems", file=sys.stderr)
            failed += 1
        else:
            print(f"ok   {name}")
    return 1 if failed else 0


def main() -> int:
    """Run the self-test or check the repository; return the exit status."""
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--self-test", action="store_true")
    args = parser.parse_args()
    if args.self_test:
        return self_test()
    found = problems((ROOT / CONFIG).read_text(encoding="utf-8"), tracked_files())
    for line in found:
        print(f"codacy-config: {line}", file=sys.stderr)
    return 1 if found else 0


if __name__ == "__main__":
    sys.exit(main())
